import{_ as e,o as r,c as s,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"執行狀態","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/service-status.md","filePath":"zh-TW/user-guide/settings/service-status.md","lastUpdated":1785993908000}'),o={name:"zh-TW/user-guide/settings/service-status.md"};function n(i,t,l,g,p,c){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="執行狀態" tabindex="-1">執行狀態 <a class="header-anchor" href="#執行狀態" aria-label="Permalink to &quot;執行狀態&quot;">​</a></h1><p>管理背景索引服務，並提供其記錄的即時檢視。</p><h2 id="服務控制" tabindex="-1">服務控制 <a class="header-anchor" href="#服務控制" aria-label="Permalink to &quot;服務控制&quot;">​</a></h2><p>狀態卡片會顯示提權索引服務目前的狀態——<strong>安裝中</strong>、<strong>索引中</strong>、<strong>就緒</strong>(附即時檔案/資料夾數量)或<strong>錯誤</strong>——並配有對應的圖示(旋轉指示器、勾選或錯誤標記)。</p><p>只有在服務尚未安裝或發生錯誤時才會出現<strong>安裝並啟動服務</strong>按鈕;一旦安裝完成並正常執行，這個頁面上就沒有手動啟動/停止/解除安裝的控制項了——服務預設應該一直在背景執行。</p><h2 id="記錄" tabindex="-1">記錄 <a class="header-anchor" href="#記錄" aria-label="Permalink to &quot;記錄&quot;">​</a></h2><p>三個分頁 —— <strong>App</strong>、<strong>Hook</strong>、<strong>Service</strong> —— 分別對應 Lertaro 執行的三個處理程序(你實際互動的使用者態 App、鍵盤鉤子處理程序、提權的背景索引服務)。每個分頁顯示對應處理程序的記錄行，按層級著色。</p><ul><li><strong>層級篩選</strong>下拉式選單 —— 全部 / 錯誤 / 警告 / 資訊 / 偵錯。</li><li><strong>搜尋框</strong> —— 按關鍵字篩選目前顯示的行，可與層級篩選疊加使用。</li><li><strong>清空記錄</strong> 按鈕 —— 清空目前選取分頁的記錄。清空 Service 分頁的記錄會透過服務本身來完成 (App 處理程序沒有權限直接改動它);App 和 Hook 的記錄由於是使用者態檔案，可以直接清空。</li></ul><p>排查問題時應該最先看這裡——見<a href="./../troubleshooting.html#還是沒解決">疑難排解</a>。</p>',9)])])}const h=e(o,[["render",n]]);export{u as __pageData,h as default};
